package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TextBuffer_contentsAsDecimal_TriageGen1Test {

    private BufferRecycler _recycler;
    private TextBuffer _textBuffer;

    @Before
    public void setUp() {
        _recycler = new BufferRecycler();
        _textBuffer = new TextBuffer(_recycler);
    }

    @Test
    public void testContentsAsDecimal_WithPreCutArray() throws Exception {
        // To trigger the first branch: if (_resultArray != null)
        // Since _resultArray is private, we simulate the state by using reflection 
        // or assuming the internal state is set via internal logic. 
        // However, in standard Jackson TextBuffer, _resultArray is set by internal parsing.
        // We will use reflection to force this state for branch coverage.
        java.lang.reflect.Field resultArrayField = TextBuffer.class.getDeclaredField("_resultArray");
        resultArrayField.setAccessible(true);
        byte[] mockArray = "123.45".getBytes();
        resultArrayField.set(_textBuffer, mockArray);

        BigDecimal expected = new BigDecimal("123.45");
        // Note: NumberInput.parseBigDecimal behavior depends on the byte content
        // We expect the method to call NumberInput.parseBigDecimal(_resultArray)
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    @Test
    public void testContentsAsDecimal_WithSharedBuffer() throws Exception {
        // To trigger the second branch: if (_inputStart >= 0)
        // We use resetWithShared to set _inputBuffer, _inputStart, and _inputLen
        char[] sharedBuf = "456.78".toCharArray();
        _textBuffer.resetWithShared(sharedBuf, 0, sharedBuf.length);

        BigDecimal expected = new BigDecimal("456.78");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    @Test
    public void testContentsAsDecimal_WithSingleBuffer() throws Exception {
        // To trigger the third branch: if (_segmentSize == 0)
        // We use append to fill the current segment. 
        // In TextBuffer, _segmentSize is 0 if we haven't finished segments/switched to shared/resultArray.
        _textBuffer.append("789.01");

        BigDecimal expected = new BigDecimal("789.01");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    @Test
    public void testContentsAsDecimal_WithAggregatedSegments() throws Exception {
        // To trigger the fourth branch: (the aggregated case)
        // This happens when _resultArray is null, _inputStart < 0, AND _segmentSize > 0
        // _segmentSize > 0 occurs after multiple segments are finished.

        _textBuffer.append("123");
        _textBuffer.finishCurrentSegment(); // This sets _segmentSize > 0
        _textBuffer.append(".456");

        BigDecimal expected = new BigDecimal("123.456");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }

    @Test(expected = NumberFormatException.class)
    public void testContentsAsDecimal_InvalidFormat() throws Exception {
        _textBuffer.append("not_a_number");
        _textBuffer.contentsAsDecimal();
    }

    @Test
    public void testContentsAsDecimal_Empty() throws Exception {
        // Testing edge case of empty buffer
        _textBuffer.append("");
        // Depending on NumberInput implementation, empty might throw or be 0.
        // For Jackson, usually results in an error or specific behavior.
        try {
            BigDecimal result = _textBuffer.contentsAsDecimal();
            // If it doesn't throw, check if it's handled.
        } catch (NumberFormatException e) {
            // Expected for empty string in many BigDecimal parsers
        }
    }
}
